// word helper: target, reading, mn, type, examples[[target,mn]], extra{syn,ant,rel,mn(mnemonic),emoji,past,pastParticiple}
function w(target, reading, mn, type, examples = [], extra = {}) {
  const id = extra.id || (reading || target).toLowerCase().replace(/[^a-z0-9]+/g, '-') || encodeURIComponent(target);
  return {
    id,
    target, reading, mn, type,
    word: target, ipa: reading, // aliases for UI compatibility
    examples: examples.map(([t, m]) => ({ en: t, mn: m })),
    synonyms: extra.syn || [], antonyms: extra.ant || [], related: extra.rel || [],
    mnemonic: extra.mn || '', emoji: extra.emoji || '',
    pastSimple: extra.past || '', pastParticiple: extra.pastParticiple || '',
  };
}

