const WORDS = { zh: ZH, en: EN, ja: {}, ko: {} };

const BULK = { zh: BULK_ZH, en: BULK_EN };

// getCourses is a pure function of `lang` over static module data — the result
// never changes at runtime, so cache it per language instead of rebuilding the
// whole catalog (now 700+ words across categories) on every call/render.
const _coursesCache = {};
export function getCourses(lang = 'zh') {
  if (_coursesCache[lang]) return _coursesCache[lang];
  const data = WORDS[lang] || {};
  const bulk = BULK[lang] || {};
  const result = CATEGORY_META.map(c => {
    const base = data[c.id] || [];
    const extraRaw = bulk[c.id] || [];
    const seen = new Set(base.map(w => w.target));
    const extra = extraRaw
      .filter(([t]) => !seen.has(t))
      .map(([t, r, m, ty]) => w(t, r, m, ty || 'Нэр үг', [], { emoji: '' }));
    return { ...c, words: [...base, ...extra] };
  });
  _coursesCache[lang] = result;
  return result;
}
export function findCategory(lang, id) { return getCourses(lang).find(c => c.id === id); }
export function findWord(lang, catId, wid) {
  const c = findCategory(lang, catId);
  return c ? c.words.find(x => x.id === wid) : null;
}
